prior=json.loads((b.OUT/'changes.json').read_text());assert len(prior)==883
_,Q,A=qa.audit(str(b.DST));D=json.loads((b.OUT/'decisions.json').read_text());extra=[]
def rewrite(qid,key,stem,opts,exps,reason,sources,verdicts):
 for field,old,new in [('stem',[Q[qid]['stem']],[stem]),('options',Q[qid]['opts'],opts),('explanations',A['A_'+qid[2:]]['txt'],exps)]:
  for i,(before,after) in enumerate(zip(old,new)):
   if html.unescape(before)==after:continue
   extra.append(dict(id=qid,field=field,index=None if field=='stem' else i,before=html.unescape(before),after=after,reason=reason,sources=sources,applied=True,before_version='第47修正バッチ作業稿'))
 D[qid].update(status='確認済み',fixes_applied=True,independent_answer=key,sources=sources,option_verdicts=verdicts,reason=reason,stem_review='取得した本文の定義と条件に限定し、4肢を独立判定。',explanation_review='全4解説を根拠本文へ照合。本文にない一般的効果・全称命題を撤去。',unresolved='',multiple_correct_risk='なし：指定された定義・手順に合うのは正答のみ',no_correct_risk='なし：独立正答'+str(key))
from docx import Document
p=Document(b.DST).paragraphs
case_after=['中級クラスでは「日本の年中行事」というエッセイを読む授業を行った。教師は本文を読む前に「あなたの国にはどんな年中行事がありますか」と質問し、数分間ペアで話し合わせた。年中行事についての既有知識を思い出し、本文理解の手がかりにすることが導入の目的だった。授業目標は大意と本文に記された細部の両方の理解であり、導入での発音や文法の採点は行わなかった。', '本文を読んだ学習者の多くは「お盆」や「七五三」などの未習語彙があっても、大まかな流れを推測して読み進められた。学習者は、知っている年中行事の知識を手がかりに内容を予測したと報告した。ただし、この報告だけから他の処理が働かなかったとは判断しない。', '読解後、教師は「なぜ七五三では子どもに千歳飴を渡すのか」と細部を問う質問をしたが、正確に答えた学習者は少なかった。答えとなる理由は本文に明記されていた。教師は、本文の該当箇所を根拠に説明できるかを次回も確認し、結果を踏まえて活動を見直すことにした。']
for old,new in zip([p[2803].text,p[2804].text,p[2805].text],case_after):
 extra.append(dict(id='CASE_O_05',field='case_text',index=None,before=old,after=new,reason='授業目標、既有知識活用の自己報告、細部への答えが本文に存在する条件を明示。活動結果だけで認知過程・文化知識・指導の因果効果を断定しない架空ケースへ限定。',sources=['S103','S106'],applied=True,before_version='第47修正バッチ作業稿'))
rewrite('Q_O_021',2,Q['Q_O_021']['stem'],Q['Q_O_021']['opts'],
 ['このケースの導入は漢字を書き取る活動として設定されていません。','教師が明示した目的は年中行事の既有知識を本文理解に利用することです。これはスキーマを活用して内容を予測する処理と対応します。','このケースでは導入の文法採点を行わないと明記されています。','このケースでは導入の発音採点を行わないと明記されています。'],
 '活動の形式から唯一の目的を推測せず、ケースの教師の目的と評価条件を明示して判定。',['S106'],['設定された活動と異なる','教師の明示目的とスキーマの機能に一致','文法採点なしの条件と不一致','発音採点なしの条件と不一致'])
rewrite('Q_O_022',4,
 '学習者が年中行事の既有知識を使って内容を予測したという報告に対応する処理として、最も適当なものを選べ。',
 ['文字や音の形式の分析だけを行う処理','文の構造の分析だけを行う処理','個々の語の解読だけを行い、背景知識を使わない処理','スキーマを使って内容を予測するトップダウン処理'],
 ['報告には背景知識を使う予測が含まれ、文字や音の形式だけの分析とは異なります。黙読で音に関する処理が働かないという意味ではありません。','背景知識を使う予測を、文の構造だけの分析とは説明できません。','個々の語の解読だけでは、報告された背景知識による予測を説明していません。','原論文は既有のスキーマによる予測をトップダウン処理と説明します。この報告はそれと対応しますが、ボトムアップ処理が働かなかったことを示すものではありません。'],
 '大意理解という結果だけから処理を同定せず、既有知識を使った予測の自己報告に限定。黙読で音韻処理が関係しないという誤った排除を撤去。',['S106'],['背景知識を使う条件を除外して誤り','背景知識を使う条件を除外して誤り','背景知識を使う条件を否定して誤り','スキーマによる予測の定義に一致'])
